/* TOPに戻る 追従ボタン（全ページ共通・画像埋め込み・自己完結）
   新しいページに設置する場合は、そのページの </body> 直前に次の1行を追加するだけ:
   <script src="totop.js" defer></script>  （サブフォルダのページなら相対パスを調整） */
(function(){
  var IMG='data:image/png;base64,';
  var CSS="#toTop{position:fixed;right:20px;bottom:20px;z-index:120;background:none;border:0;padding:0;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;-webkit-tap-highlight-color:transparent;opacity:0;visibility:hidden;transform:translateY(10px);transition:opacity .25s,transform .25s,visibility .25s;}#toTop.show{opacity:1;visibility:visible;transform:none;}.tt-bubble{position:relative;background:#fff;color:#23201A;font-family:'M PLUS Rounded 1c',sans-serif;font-weight:800;font-size:12px;line-height:1;border:2px solid #23201A;border-radius:999px;padding:6px 12px;white-space:nowrap;box-shadow:2px 2px 0 #23201A;}.tt-bubble::after{content:'';position:absolute;left:50%;bottom:-8px;transform:translateX(-50%);border:6px solid transparent;border-top-color:#23201A;}.tt-bubble::before{content:'';position:absolute;left:50%;bottom:-4px;transform:translateX(-50%);border:5px solid transparent;border-top-color:#fff;z-index:1;}#toTop img{width:66px;height:auto;display:block;filter:drop-shadow(2px 3px 3px rgba(0,0,0,.22));transition:transform .15s;}#toTop:hover img{transform:translateY(-3px) scale(1.05);}#toTop:active img{transform:translateY(0) scale(.97);}@media (prefers-reduced-motion:reduce){#toTop,#toTop img{transition:none;}}";
  function init(){
    if(document.getElementById('toTop')) return;
    var st=document.createElement('style'); st.textContent=CSS; document.head.appendChild(st);
    var btn=document.createElement('button'); btn.id='toTop'; btn.type='button'; btn.setAttribute('aria-label','ページ上部へ戻る');
    var bub=document.createElement('span'); bub.className='tt-bubble'; bub.textContent='TOPに戻る';
    var img=document.createElement('img'); img.src=IMG; img.alt=''; img.setAttribute('aria-hidden','true');
    btn.appendChild(bub); btn.appendChild(img);
    btn.addEventListener('click', function(){ window.scrollTo({top:0, behavior:'smooth'}); });
    document.body.appendChild(btn);
    function onScroll(){ if((window.pageYOffset||document.documentElement.scrollTop)>200){ btn.classList.add('show'); } else { btn.classList.remove('show'); } }
    window.addEventListener('scroll', onScroll, {passive:true}); onScroll();
  }
  if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', init); } else { init(); }
})();
